SELECT s.sku_id,COUNT(*) AS amount FROM prop_sn_instance s WHERE s.sku_id IN 
#{value}
 AND s.instance_status='idle' AND NOT EXISTS(SELECT 1 FROM prop_sn_adjustment_item i JOIN prop_sn_adjustment_audit a ON a.id=i.adjustment_audit_id WHERE i.sn_id=s.id AND a.audit_status='pending') AND NOT EXISTS(SELECT 1 FROM inventory_reservation r WHERE r.sn_id=s.id AND r.reservation_status IN ('held','paid_locked','renting','overdue_holding','disputed_holding') AND r.occupy_start_date<=#{endDate} AND >=#{startDate}) GROUP BY s.sku_id

SELECT id, current_order_id, instance_status, qr_code_id, remark, sn_code, status_changed_at, status_remark, updated_at, version FROM prop_sn_instance WHERE sku_id=#{instanceQueryDTO.skuId}
 AND instance_status=#{instanceQueryDTO.status}
 ORDER BY created_at DESC,id DESC LIMIT #{instanceQueryDTO.limit} OFFSET #{instanceQueryDTO.offset}
